var report="Tools/UI/SharedGameEndVerification.txt";System.IO.File.WriteAllText(report,"Game end shared canvas check\n");int stage=0,wait=0,last=-1;double start=UnityEditor.EditorApplication.timeSinceStartup,shown=0;UnityEditor.EditorApplication.CallbackFunction tick=null;System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;UnityEngine.Time.timeScale=1;UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene=null;UnityEditor.EditorApplication.isPlaying=false;};
tick=()=>{try{if(!UnityEditor.EditorApplication.isPlaying)return;UnityEngine.Application.runInBackground=true;if(UnityEditor.EditorApplication.timeSinceStartup-start>60)throw new System.Exception("timeout");if(last==UnityEngine.Time.frameCount)return;last=UnityEngine.Time.frameCount;if(stage==0){if(StageManager.Instance==null||++wait<20)return;StageManager.Instance.StopRun();GameEndScreenController.ShowGameOver();shown=UnityEditor.EditorApplication.timeSinceStartup;stage=1;return;}if(UnityEditor.EditorApplication.timeSinceStartup-shown<8)return;var controller=UnityEngine.Object.FindFirstObjectByType<GameEndScreenController>();var overlay=(UnityEngine.GameObject)typeof(GameEndScreenController).GetField("overlay",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(controller);if(!overlay.activeInHierarchy)throw new System.Exception("game over hidden");foreach(var b in overlay.GetComponentsInChildren<UnityEngine.UI.Button>()){var rect=(UnityEngine.RectTransform)b.transform;var canvas=b.GetComponentInParent<UnityEngine.Canvas>();var position=UnityEngine.RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,rect.TransformPoint(rect.rect.center));var data=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=position};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(data,hits);if(!hits.Any(h=>h.gameObject==b.gameObject||h.gameObject.transform.IsChildOf(b.transform)))throw new System.Exception("button not clickable "+b.name+" at "+position+" hits="+string.Join(",",hits.Select(h=>h.gameObject.name))+" groups="+string.Join(",",b.GetComponentsInParent<UnityEngine.CanvasGroup>(true).Select(g=>g.name+":"+g.alpha+":"+g.blocksRaycasts))+" interactable="+b.interactable+" progress="+typeof(GameEndScreenController).GetField("revealProgress",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(controller)+" canvasCamera="+canvas.worldCamera);}int count=UnityEngine.Object.FindObjectsByType<UnityEngine.Canvas>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Count(c=>c.gameObject.scene.name=="Stage1");if(count!=2)throw new System.Exception("count="+count);System.IO.File.AppendAllText(report,"PASS visible game over overlay, buttons raycastable, only two Stage1 canvases\nCOMPLETE\n");finish();}catch(System.Exception e){System.IO.File.AppendAllText(report,"FAIL "+e+"\n");finish();}};UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.SceneAsset>("Assets/Scenes/Stage1.unity");UnityEditor.EditorApplication.update+=tick;UnityEditor.EditorApplication.isPlaying=true;return "Game end verification started";
